			log.Error(r.Context(), "Error deleting tracks from playlist", "playlistId", playlistId, "ids", ids, err)
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		var resp []byte
		if len(ids) == 1 {
			resp = []byte(`{"id":"` + ids[0] + `"}`)
